-- TU DONG SINH tu entity TypeORM (database/generate-schema.ts). Khong sua tay; sua entity roi chay npm run db:schema.
-- MySQL 8.0+ : mysql -u root -p voucher_platform < database/mysql/schema.sql
-- Tao CSDL truoc: CREATE DATABASE voucher_platform CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
SET NAMES utf8mb4;
SET time_zone = '+00:00';

CREATE TABLE `audit_logs` (`id` varchar(36) NOT NULL, `actorUserId` varchar(255) NULL, `action` varchar(255) NOT NULL, `entityType` varchar(255) NOT NULL, `entityId` varchar(255) NOT NULL, `detail` json NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), INDEX `IDX_13c69424c440a0e765053feb4b` (`entityType`, `entityId`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `brands` (`id` varchar(36) NOT NULL, `ownerUserId` varchar(255) NOT NULL, `name` varchar(255) NOT NULL, `logo` varchar(255) NULL, `description` text NULL, `categoryId` varchar(255) NULL, `contactInfo` varchar(255) NULL, `bankInfo` varchar(255) NULL, `status` enum ('PENDING', 'APPROVED', 'REJECTED', 'SUSPENDED') NOT NULL DEFAULT 'PENDING', `rejectReason` varchar(255) NULL, `approvedAt` datetime NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `campaign_stores` (`campaignId` varchar(255) NOT NULL, `storeId` varchar(255) NOT NULL, PRIMARY KEY (`campaignId`, `storeId`)) ENGINE=InnoDB;
CREATE TABLE `categories` (`id` varchar(36) NOT NULL, `name` varchar(255) NOT NULL, `icon` varchar(255) NULL, `displayOrder` int NOT NULL DEFAULT '0', PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `device_tokens` (`id` varchar(36) NOT NULL, `userId` varchar(255) NOT NULL, `token` varchar(255) NOT NULL, `platform` varchar(255) NOT NULL, `lastActiveAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `favorites` (`id` varchar(36) NOT NULL, `userId` varchar(255) NOT NULL, `targetType` enum ('BRAND', 'CAMPAIGN') NOT NULL, `targetId` varchar(255) NOT NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `notification_settings` (`userId` varchar(255) NOT NULL, `type` varchar(255) NOT NULL, `enabled` tinyint NOT NULL DEFAULT 1, PRIMARY KEY (`userId`, `type`)) ENGINE=InnoDB;
CREATE TABLE `notifications` (`id` varchar(36) NOT NULL, `userId` varchar(255) NOT NULL, `type` varchar(255) NOT NULL, `title` varchar(255) NOT NULL, `body` text NOT NULL, `data` json NULL, `dedupeKey` varchar(255) NULL, `readAt` datetime NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), INDEX `IDX_21e65af2f4f242d4c85a92aff4` (`userId`, `createdAt`), UNIQUE INDEX `IDX_4e652c0d7bd0781daccfea1e11` (`dedupeKey`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `orders` (`id` varchar(36) NOT NULL, `userId` varchar(255) NOT NULL, `campaignId` varchar(255) NOT NULL, `quantity` int NOT NULL, `unitPrice` bigint NOT NULL, `totalAmount` bigint NOT NULL, `commissionRate` decimal(5,4) NULL, `refundedAmount` bigint NOT NULL DEFAULT '0', `status` enum ('PENDING', 'PAID', 'CANCELLED', 'FULFILLED', 'REFUNDED_OVERSOLD', 'PAYMENT_MISMATCH') NOT NULL DEFAULT 'PENDING', `paymentOrderCode` bigint NULL, `paymentUrl` text NULL, `reservedUntil` datetime NOT NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `paidAt` datetime NULL, `cancelledAt` datetime NULL, UNIQUE INDEX `IDX_898a931dfb73a87693b3c51e12` (`paymentOrderCode`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `otp_codes` (`id` varchar(36) NOT NULL, `email` varchar(255) NOT NULL, `purpose` enum ('REGISTER', 'LOGIN', 'ACTIVATE', 'RESET_PASSWORD') NOT NULL, `codeHash` varchar(255) NOT NULL, `attempts` int NOT NULL DEFAULT '0', `expiresAt` datetime NOT NULL, `usedAt` datetime NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), INDEX `IDX_d9a9c6325dfb1d16b5f6b2f6ac` (`email`, `purpose`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `payment_refunds` (`id` varchar(36) NOT NULL, `paymentId` varchar(255) NOT NULL, `amount` bigint NOT NULL, `reasonType` enum ('CUSTOMER_REQUEST', 'OVERSOLD', 'MISMATCH') NOT NULL, `mode` enum ('AUTO', 'MANUAL') NOT NULL, `status` enum ('PROCESSING', 'COMPLETED', 'FAILED') NOT NULL DEFAULT 'PROCESSING', `gatewayRefundId` varchar(255) NULL, `processedBy` varchar(255) NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `completedAt` datetime NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `payments` (`id` varchar(36) NOT NULL, `orderId` varchar(255) NOT NULL, `gateway` varchar(255) NOT NULL, `gatewayTxnId` varchar(255) NOT NULL, `amount` bigint NOT NULL, `status` enum ('SUCCESS', 'FAILED', 'CANCELLED') NOT NULL, `rawPayload` json NULL, `receivedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE INDEX `IDX_8c55510fcf2450a133f0f77fdd` (`gatewayTxnId`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `redeem_tokens` (`id` varchar(36) NOT NULL, `voucherItemId` varchar(255) NOT NULL, `nonce` varchar(255) NOT NULL, `otpCode` varchar(255) NOT NULL, `issuedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `expiresAt` datetime NOT NULL, `usedAt` datetime NULL, `revokedAt` datetime NULL, INDEX `IDX_cf00847498e2e51564cbc7a799` (`otpCode`), UNIQUE INDEX `IDX_c3a9d3db15586bac81783574d2` (`nonce`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `redemption_logs` (`id` varchar(36) NOT NULL, `voucherItemId` varchar(255) NOT NULL, `storeId` varchar(255) NOT NULL, `staffUserId` varchar(255) NOT NULL, `billAmount` bigint NULL, `billUpdatedAt` datetime NULL, `redeemedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `method` enum ('QR', 'OTP') NOT NULL DEFAULT 'QR', UNIQUE INDEX `IDX_cd36021dbb7b82a771e6377516` (`voucherItemId`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `refresh_tokens` (`id` varchar(36) NOT NULL, `userId` varchar(255) NOT NULL, `deviceId` varchar(255) NOT NULL, `tokenHash` varchar(255) NOT NULL, `activeStoreId` varchar(255) NULL, `expiresAt` datetime NOT NULL, `revokedAt` datetime NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE INDEX `IDX_c25bc63d248ca90e8dcc1d92d0` (`tokenHash`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `refund_requests` (`id` varchar(36) NOT NULL, `voucherItemId` varchar(255) NOT NULL, `userId` varchar(255) NOT NULL, `reason` text NULL, `status` enum ('REQUESTED', 'PROCESSING', 'REJECTED', 'MANUAL_PENDING', 'COMPLETED', 'FAILED') NOT NULL DEFAULT 'REQUESTED', `decidedAt` datetime NULL, `paymentRefundId` varchar(255) NULL, `rejectReason` varchar(255) NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `reviews` (`id` varchar(36) NOT NULL, `campaignId` varchar(255) NOT NULL, `voucherItemId` varchar(255) NOT NULL, `userId` varchar(255) NOT NULL, `rating` int NOT NULL, `comment` text NULL, `brandReply` text NULL, `brandRepliedAt` datetime NULL, `status` enum ('VISIBLE', 'HIDDEN') NOT NULL DEFAULT 'VISIBLE', `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE INDEX `IDX_2cfc03c24df288f85070c57f57` (`userId`, `campaignId`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `settlement_items` (`id` varchar(36) NOT NULL, `settlementId` varchar(255) NOT NULL, `voucherItemId` varchar(255) NOT NULL, `orderId` varchar(255) NOT NULL, `amount` bigint NOT NULL, `commissionRate` decimal(5,4) NOT NULL, `commissionAmount` bigint NOT NULL, UNIQUE INDEX `IDX_e62e18c3987bb9a4e45131ed05` (`voucherItemId`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `settlements` (`id` varchar(36) NOT NULL, `brandId` varchar(255) NOT NULL, `periodStart` datetime NOT NULL, `periodEnd` datetime NOT NULL, `grossRevenue` bigint NOT NULL, `voucherCount` int NOT NULL DEFAULT '0', `commissionAmount` bigint NOT NULL, `payableAmount` bigint NOT NULL, `status` enum ('PENDING', 'PAID') NOT NULL DEFAULT 'PENDING', `paidAt` datetime NULL, `bankTxnRef` varchar(255) NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `staff_assignments` (`id` varchar(36) NOT NULL, `userId` varchar(255) NOT NULL, `storeId` varchar(255) NOT NULL, `assignedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `active` tinyint NOT NULL DEFAULT 1, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `stores` (`id` varchar(36) NOT NULL, `brandId` varchar(255) NOT NULL, `name` varchar(255) NOT NULL, `address` varchar(255) NOT NULL, `latitude` double NULL, `longitude` double NULL, `phone` varchar(255) NULL, `openingHours` varchar(255) NULL, `status` tinyint NOT NULL DEFAULT 1, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `system_configs` (`key` varchar(255) NOT NULL, `value` text NOT NULL, `updatedBy` varchar(255) NULL, `updatedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (`key`)) ENGINE=InnoDB;
CREATE TABLE `users` (`id` varchar(36) NOT NULL, `email` varchar(255) NOT NULL, `passwordHash` varchar(255) NULL, `fullName` varchar(255) NULL, `phone` varchar(255) NULL, `avatar` varchar(255) NULL, `role` enum ('GUEST', 'CUSTOMER', 'BRAND_OWNER', 'STORE_STAFF', 'ADMIN') NOT NULL DEFAULT 'CUSTOMER', `status` enum ('PENDING_ACTIVATION', 'ACTIVE', 'INACTIVE') NOT NULL DEFAULT 'ACTIVE', `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), UNIQUE INDEX `IDX_97672ac88f789774dd47f7c8be` (`email`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `voucher_campaigns` (`id` varchar(36) NOT NULL, `brandId` varchar(255) NOT NULL, `categoryId` varchar(255) NULL, `title` varchar(255) NOT NULL, `image` varchar(255) NULL, `description` text NULL, `terms` text NULL, `voucherType` enum ('DISCOUNT', 'PREPAID', 'COMBO') NOT NULL, `salePrice` bigint NOT NULL, `faceValue` bigint NOT NULL, `discountType` enum ('AMOUNT', 'PERCENT') NULL, `discountValue` bigint NULL, `maxDiscount` bigint NULL, `comboItems` text NULL, `totalQuantity` int NOT NULL, `soldQuantity` int NOT NULL DEFAULT '0', `reservedQuantity` int NOT NULL DEFAULT '0', `limitPerUser` int NOT NULL DEFAULT '5', `saleStartAt` datetime NOT NULL, `saleEndAt` datetime NOT NULL, `voucherExpireAt` datetime NOT NULL, `status` enum ('DRAFT', 'PENDING', 'APPROVED', 'PUBLISHED', 'SOLD_OUT', 'PAUSED', 'ENDED') NOT NULL DEFAULT 'DRAFT', `rejectReason` varchar(255) NULL, `submittedAt` datetime NULL, `approvedBy` varchar(255) NULL, `approvedAt` datetime NULL, `createdAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE `voucher_items` (`id` varchar(36) NOT NULL, `orderId` varchar(255) NOT NULL, `campaignId` varchar(255) NOT NULL, `userId` varchar(255) NOT NULL, `code` varchar(255) NOT NULL, `secretKey` varchar(255) NOT NULL, `status` enum ('ACTIVE', 'REFUND_PENDING', 'USED', 'REFUNDED', 'EXPIRED') NOT NULL DEFAULT 'ACTIVE', `issuedAt` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), `usedAt` datetime NULL, `expireAt` datetime NOT NULL, `refundableUntil` datetime NOT NULL, `lockVersion` int NOT NULL, UNIQUE INDEX `IDX_78606c39a514b953ab7b8d4106` (`code`), PRIMARY KEY (`id`)) ENGINE=InnoDB;
